class Solution:
    def outerTrees(self, trees: List[List[int]]) -> List[float]:
        import math

        def circle2(a, b):
            return [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2,
                    math.hypot(a[0] - b[0], a[1] - b[1]) / 2]

        def circle3(A, B, C):
            d = 2 * (A[0] * (B[1] - C[1]) + B[0] * (C[1] - A[1]) + C[0] * (A[1] - B[1]))
            if d == 0:
                return None
            a2 = A[0] ** 2 + A[1] ** 2
            b2 = B[0] ** 2 + B[1] ** 2
            c2 = C[0] ** 2 + C[1] ** 2
            x = (a2 * (B[1] - C[1]) + b2 * (C[1] - A[1]) + c2 * (A[1] - B[1])) / d
            y = (a2 * (C[0] - B[0]) + b2 * (A[0] - C[0]) + c2 * (B[0] - A[0])) / d
            return [x, y, math.hypot(x - A[0], y - A[1])]

        def covers(c):
            return all(math.hypot(px - c[0], py - c[1]) <= c[2] + 1e-7
                       for px, py in trees)

        best = None
        n = len(trees)
        for i in range(n):
            for j in range(i + 1, n):
                cands = [circle2(trees[i], trees[j])]
                for k in range(j + 1, n):
                    c = circle3(trees[i], trees[j], trees[k])
                    if c is not None:
                        cands.append(c)
                for c in cands:
                    if covers(c) and (best is None or c[2] < best[2]):
                        best = c
        if best is None:
            best = [float(trees[0][0]), float(trees[0][1]), 0.0]
        return best

