class Solution {
public:
    vector<double> outerTrees(vector<vector<int>>& trees) {
        int n = trees.size();
        auto circle2 = [](const vector<int>& a, const vector<int>& b) {
            double cx = (a[0] + b[0]) / 2.0, cy = (a[1] + b[1]) / 2.0;
            double r = hypot((double)a[0] - b[0], (double)a[1] - b[1]) / 2;
            return vector<double>{cx, cy, r};
        };
        auto circle3 = [](const vector<int>& A, const vector<int>& B,
                          const vector<int>& C) {
            double d = 2.0 * (A[0] * (B[1] - C[1]) + B[0] * (C[1] - A[1])
                              + C[0] * (A[1] - B[1]));
            if (d == 0) return vector<double>{0.0, 0.0, -1.0};
            double a2 = (double)A[0] * A[0] + (double)A[1] * A[1];
            double b2 = (double)B[0] * B[0] + (double)B[1] * B[1];
            double c2 = (double)C[0] * C[0] + (double)C[1] * C[1];
            double x = (a2 * (B[1] - C[1]) + b2 * (C[1] - A[1]) + c2 * (A[1] - B[1])) / d;
            double y = (a2 * (C[0] - B[0]) + b2 * (A[0] - C[0]) + c2 * (B[0] - A[0])) / d;
            return vector<double>{x, y, hypot(x - A[0], y - A[1])};
        };
        auto covers = [&](const vector<double>& c) {
            for (auto& t : trees)
                if (hypot((double)t[0] - c[0], (double)t[1] - c[1]) > c[2] + 1e-7)
                    return false;
            return true;
        };
        vector<double> best;
        for (int i = 0; i < n; ++i)
            for (int j = i + 1; j < n; ++j) {
                vector<vector<double>> cands{circle2(trees[i], trees[j])};
                for (int k = j + 1; k < n; ++k) {
                    auto c = circle3(trees[i], trees[j], trees[k]);
                    if (c[2] >= 0) cands.push_back(move(c));
                }
                for (auto& c : cands)
                    if (covers(c) && (best.empty() || c[2] < best[2])) best = c;
            }
        if (best.empty())
            best = {(double)trees[0][0], (double)trees[0][1], 0.0};
        return best;
    }
};

