class Solution {
    public double[] outerTrees(int[][] trees) {
        int n = trees.length;
        double[] best = null;
        for (int i = 0; i < n; ++i)
            for (int j = i + 1; j < n; ++j) {
                List<double[]> cands = new ArrayList<>();
                cands.add(circle2(trees[i], trees[j]));
                for (int k = j + 1; k < n; ++k) {
                    double[] c = circle3(trees[i], trees[j], trees[k]);
                    if (c[2] >= 0) cands.add(c);
                }
                for (double[] c : cands)
                    if (covers(trees, c) && (best == null || c[2] < best[2])) best = c;
            }
        if (best == null)
            best = new double[]{trees[0][0], trees[0][1], 0};
        return best;
    }

    private double[] circle2(int[] a, int[] b) {
        return new double[]{(a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0,
                Math.hypot(a[0] - b[0], a[1] - b[1]) / 2};
    }

    private double[] circle3(int[] A, int[] B, int[] C) {
        double d = 2.0 * (A[0] * (B[1] - C[1]) + B[0] * (C[1] - A[1]) + C[0] * (A[1] - B[1]));
        if (d == 0) return new double[]{0, 0, -1};
        double a2 = A[0] * A[0] + A[1] * A[1];
        double b2 = B[0] * B[0] + B[1] * B[1];
        double c2 = C[0] * C[0] + C[1] * C[1];
        double x = (a2 * (B[1] - C[1]) + b2 * (C[1] - A[1]) + c2 * (A[1] - B[1])) / d;
        double y = (a2 * (C[0] - B[0]) + b2 * (A[0] - C[0]) + c2 * (B[0] - A[0])) / d;
        return new double[]{x, y, Math.hypot(x - A[0], y - A[1])};
    }

    private boolean covers(int[][] trees, double[] c) {
        for (int[] t : trees)
            if (Math.hypot(t[0] - c[0], t[1] - c[1]) > c[2] + 1e-7) return false;
        return true;
    }
}

