class Solution:
    def outerTrees(self, trees: List[List[int]]) -> List[float]:
        import math
        import random

        pts = [(float(x), float(y)) for x, y in trees]
        random.shuffle(pts)
        EPS = 1e-7

        def circle2(a, b):
            return [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2,
                    math.hypot(a[0] - b[0], a[1] - b[1]) / 2]

        def circle3(A, B, C):
            d = 2 * (A[0] * (B[1] - C[1]) + B[0] * (C[1] - A[1]) + C[0] * (A[1] - B[1]))
            if abs(d) < 1e-12:
                return None
            a2 = A[0] ** 2 + A[1] ** 2
            b2 = B[0] ** 2 + B[1] ** 2
            c2 = C[0] ** 2 + C[1] ** 2
            x = (a2 * (B[1] - C[1]) + b2 * (C[1] - A[1]) + c2 * (A[1] - B[1])) / d
            y = (a2 * (C[0] - B[0]) + b2 * (A[0] - C[0]) + c2 * (B[0] - A[0])) / d
            return [x, y, math.hypot(x - A[0], y - A[1])]

        def inside(c, p):
            return c is not None and math.hypot(p[0] - c[0], p[1] - c[1]) <= c[2] + EPS

        def smallest3(A, B, C):
            c = circle3(A, B, C)
            if c is not None:
                return c
            best = None
            for cand in (circle2(A, B), circle2(A, C), circle2(B, C)):
                if all(inside(cand, q) for q in (A, B, C)) and (best is None or cand[2] < best[2]):
                    best = cand
            return best

        c = [pts[0][0], pts[0][1], 0.0]
        for i in range(1, len(pts)):
            if inside(c, pts[i]):
                continue
            c = [pts[i][0], pts[i][1], 0.0]
            for j in range(i):
                if inside(c, pts[j]):
                    continue
                c = circle2(pts[i], pts[j])
                for k in range(j):
                    if inside(c, pts[k]):
                        continue
                    c = smallest3(pts[i], pts[j], pts[k])
        return c

