public:
    vector<double> outerTrees(vector<vector<int>>& treesInput) {
        int n = treesInput.size();
        vector<array<double, 2>> pts(n);
        for (int i = 0; i < n; ++i)
            pts[i] = {(double)treesInput[i][0], (double)treesInput[i][1]};
        unsigned long long seed = 88172645463325252ULL;
        auto rnd = [&]() {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            return seed;
        };
        for (int i = n - 1; i > 0; --i) swap(pts[i], pts[rnd() % (i + 1)]);
        const double EPS = 1e-7;
        auto circle2 = [](const array<double, 2>& a, const array<double, 2>& b) {
            return array<double, 3>{(a[0] + b[0]) / 2, (a[1] + b[1]) / 2,
                                    hypot(a[0] - b[0], a[1] - b[1]) / 2};
        };
        auto circle3 = [](const array<double, 2>& A, const array<double, 2>& B,
                          const array<double, 2>& C) {
            double d = 2 * (A[0] * (B[1] - C[1]) + B[0] * (C[1] - A[1])
                            + C[0] * (A[1] - B[1]));
            if (fabs(d) < 1e-12) return array<double, 3>{0.0, 0.0, -1.0};
            double a2 = A[0] * A[0] + A[1] * A[1];
            double b2 = B[0] * B[0] + B[1] * B[1];
            double c2 = C[0] * C[0] + C[1] * C[1];
            double x = (a2 * (B[1] - C[1]) + b2 * (C[1] - A[1]) + c2 * (A[1] - B[1])) / d;
            double y = (a2 * (C[0] - B[0]) + b2 * (A[0] - C[0]) + c2 * (B[0] - A[0])) / d;
            return array<double, 3>{x, y, hypot(x - A[0], y - A[1])};
        };
        auto inside = [&](const array<double, 3>& c, const array<double, 2>& p) {
            return hypot(p[0] - c[0], p[1] - c[1]) <= c[2] + EPS;
        };
        auto smallest3 = [&](const array<double, 2>& A, const array<double, 2>& B,
                             const array<double, 2>& C) {
            array<double, 3> c = circle3(A, B, C);
            if (c[2] >= 0) return c;
            array<array<double, 3>, 3> pairs{circle2(A, B), circle2(A, C), circle2(B, C)};
            array<double, 3> best{0.0, 0.0, -1.0};
            for (auto& cand : pairs)
                if (inside(cand, A) && inside(cand, B) && inside(cand, C)
                    && (best[2] < 0 || cand[2] < best[2]))
                    best = cand;
            return best;
        };
        array<double, 3> c{pts[0][0], pts[0][1], 0.0};
        for (int i = 1; i < n; ++i) {
            if (inside(c, pts[i])) continue;
            c = {pts[i][0], pts[i][1], 0.0};
            for (int j = 0; j < i; ++j) {
                if (inside(c, pts[j])) continue;
                c = circle2(pts[i], pts[j]);
                for (int k = 0; k < j; ++k) {
                    if (inside(c, pts[k])) continue;
                    c = smallest3(pts[i], pts[j], pts[k]);
                }
            }
        }
        return vector<double>(c.begin(), c.end());
    }
};

