class Solution {
    private static final double EPS = 1e-7;

    public double[] outerTrees(int[][] treesInput) {
        int n = treesInput.length;
        double[][] pts = new double[n][2];
        for (int i = 0; i < n; ++i) {
            pts[i][0] = treesInput[i][0];
            pts[i][1] = treesInput[i][1];
        }
        Random rnd = new Random(1);
        for (int i = n - 1; i > 0; --i) {
            int j = rnd.nextInt(i + 1);
            double[] tmp = pts[i];
            pts[i] = pts[j];
            pts[j] = tmp;
        }
        double[] c = {pts[0][0], pts[0][1], 0};
        for (int i = 1; i < n; ++i) {
            if (inside(c, pts[i])) continue;
            c = new double[]{pts[i][0], pts[i][1], 0};
            for (int j = 0; j < i; ++j) {
                if (inside(c, pts[j])) continue;
                c = circle2(pts[i], pts[j]);
                for (int k = 0; k < j; ++k) {
                    if (inside(c, pts[k])) continue;
                    c = smallest3(pts[i], pts[j], pts[k]);
                }
            }
        }
        return c;
    }

    private boolean inside(double[] c, double[] p) {
        return Math.hypot(p[0] - c[0], p[1] - c[1]) <= c[2] + EPS;
    }

    private double[] circle2(double[] a, double[] b) {
        return new double[]{(a[0] + b[0]) / 2, (a[1] + b[1]) / 2,
                Math.hypot(a[0] - b[0], a[1] - b[1]) / 2};
    }

    private double[] circle3(double[] A, double[] B, double[] C) {
        double d = 2 * (A[0] * (B[1] - C[1]) + B[0] * (C[1] - A[1]) + C[0] * (A[1] - B[1]));
        if (Math.abs(d) < 1e-12) return new double[]{0, 0, -1};
        double a2 = A[0] * A[0] + A[1] * A[1];
        double b2 = B[0] * B[0] + B[1] * B[1];
        double c2 = C[0] * C[0] + C[1] * C[1];
        double x = (a2 * (B[1] - C[1]) + b2 * (C[1] - A[1]) + c2 * (A[1] - B[1])) / d;
        double y = (a2 * (C[0] - B[0]) + b2 * (A[0] - C[0]) + c2 * (B[0] - A[0])) / d;
        return new double[]{x, y, Math.hypot(x - A[0], y - A[1])};
    }

    private double[] smallest3(double[] A, double[] B, double[] C) {
        double[] c = circle3(A, B, C);
        if (c[2] >= 0) return c;
        double[] best = null;
        for (double[] cand : new double[][]{circle2(A, B), circle2(A, C), circle2(B, C)}) {
            if (inside(cand, A) && inside(cand, B) && inside(cand, C)
                    && (best == null || cand[2] < best[2]))
                best = cand;
        }
        return best;
    }
}

